components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 12px 22px;
  border: 1px solid var(--color-brand, #BF5501);
  border-radius: 2px;
  background: var(--color-brand-ink, #8C3B00);
  color: var(--color-cream, #F4EEE7);
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.82rem;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.015em;
  cursor: pointer;
  transition: background-color 180ms ease, border-color 180ms ease, transform 180ms ease;
}
.ds-btn-primary:hover { background: var(--color-brand-strong, #A34600); }
.ds-btn-primary:active { transform: translateY(1px); }
.ds-btn-primary:focus-visible {
  outline: 2px solid var(--color-cream, #F4EEE7);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--color-charcoal, #211F1D);
}

.ds-ghost-ground {
  display: flex;
  padding: 24px;
  background: var(--color-charcoal, #211F1D);
}
.ds-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 12px 22px;
  border: 1px solid rgba(244, 238, 231, 0.62);
  border-radius: 2px;
  background: rgba(33, 31, 29, 0.36);
  color: var(--color-cream, #F4EEE7);
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
  font-size: 0.82rem;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.015em;
  cursor: pointer;
  transition: background-color 180ms ease, color 180ms ease, border-color 180ms ease, transform 180ms ease;
}
.ds-btn-ghost:hover {
  background: var(--color-cream, #F4EEE7);
  border-color: var(--color-cream, #F4EEE7);
  color: var(--color-charcoal, #211F1D);
}
.ds-btn-ghost:active { transform: translateY(1px); }
.ds-btn-ghost:focus-visible {
  outline: 2px solid var(--color-cream, #F4EEE7);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--color-charcoal, #211F1D);
}

.ds-brand-band {
  display: flex;
  padding: 32px;
  background: linear-gradient(135deg, var(--color-brand-strong, #A34600) 0%, var(--color-brand-deep, #7A3200) 100%);
}
.ds-logo-plaque {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 24px 28px;
  border: 1px solid var(--color-brand, #BF5501);
  border-radius: 0;
  background: var(--color-cream, #F4EEE7);
  color: var(--color-brand, #BF5501);
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
}
.ds-logo-mark {
  font-family: "Bodoni Moda", Georgia, serif;
  font-size: 2.2rem;
  line-height: 1;
}
.ds-logo-wordmark {
  color: var(--color-brand-ink, #8C3B00);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.14em;
}

.ds-nav {
  display: flex;
  align-items: center;
  gap: 26px;
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
}
.ds-nav-link {
  position: relative;
  padding-block: 8px;
  color: var(--color-text-dark, #292522);
  font-size: 0.8rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  text-decoration: none;
}
.ds-nav-link::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 8px;
  left: 0;
  height: 1px;
  background: var(--color-brand, #BF5501);
  transform: scaleX(0);
  transform-origin: right;
  transition: transform 220ms cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-nav-link:hover::after,
.ds-nav-link[aria-current="location"]::after {
  transform: scaleX(1);
  transform-origin: left;
}
.ds-nav-link[aria-current="location"] { color: var(--color-brand-ink, #8C3B00); }
.ds-nav-link:focus-visible {
  outline: 2px solid var(--color-cream, #F4EEE7);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--color-charcoal, #211F1D);
}

.ds-chip {
  display: inline-flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  background: var(--color-charcoal, #211F1D);
  color: var(--color-cream, #F4EEE7);
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
}
.ds-chip-name {
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: 0.02em;
}
.ds-chip-note {
  color: var(--color-beige, #E7DCD0);
  font-size: 0.75rem;
  line-height: 1.3;
}

.ds-swatch {
  position: relative;
  display: flex;
  align-items: flex-end;
  min-height: 156px;
  padding: 12px;
  border: 1px solid rgba(33, 31, 29, 0.24);
  background: var(--color-brand, #BF5501);
}
.ds-swatch::before {
  content: "";
  position: absolute;
  inset: 9px;
  border: 1px solid rgba(33, 31, 29, 0.2);
  pointer-events: none;
}
.ds-swatch-steel { background: var(--color-charcoal, #211F1D); border-color: var(--color-charcoal, #211F1D); }
.ds-swatch-steel::before { border-color: rgba(244, 238, 231, 0.22); }
.ds-swatch-steel .ds-chip { background: var(--color-cream, #F4EEE7); color: var(--color-charcoal, #211F1D); }
.ds-swatch-steel .ds-chip-note { color: var(--color-text-muted-dark, #4A433C); }
.ds-swatch-olive { background: var(--color-olive, #7C8655); }
.ds-chip {
  position: relative;
  z-index: 1;
  display: inline-flex;
  flex-direction: column;
  gap: 2px;
  padding: 8px 10px;
  background: var(--color-charcoal, #211F1D);
  color: var(--color-cream, #F4EEE7);
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
}
.ds-chip-name { font-size: 0.75rem; font-weight: 600; line-height: 1.25; letter-spacing: 0.02em; }
.ds-chip-note { color: var(--color-beige, #E7DCD0); font-size: 0.75rem; line-height: 1.3; }

.ds-dialog {
  width: min(560px, 100%);
  padding: 42px;
  border: 1px solid var(--color-charcoal, #211F1D);
  border-radius: 0;
  background: var(--color-cream, #F4EEE7);
  color: var(--color-text-dark, #292522);
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
}
.ds-dialog-label {
  margin: 0 0 14px;
  color: var(--color-brand-ink, #8C3B00);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.ds-dialog-title {
  margin: 0;
  font-family: "Bodoni Moda", Georgia, serif;
  font-size: 1.9rem;
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.02em;
}
.ds-dialog-body {
  margin: 14px 0 22px;
  color: var(--color-text-muted-dark, #4A433C);
  font-size: 0.95rem;
  line-height: 1.6;
}
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 12px 22px;
  border: 1px solid var(--color-brand, #BF5501);
  border-radius: 2px;
  background: var(--color-brand-ink, #8C3B00);
  color: var(--color-cream, #F4EEE7);
  font-size: 0.82rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 180ms ease;
}
.ds-btn-primary:hover { background: var(--color-brand-strong, #A34600); }
.ds-btn-primary:focus-visible {
  outline: 2px solid var(--color-cream, #F4EEE7);
  outline-offset: 3px;
  box-shadow: 0 0 0 5px var(--color-charcoal, #211F1D);
}

.ds-heading {
  font-family: "Archivo", "Helvetica Neue", Arial, sans-serif;
  color: var(--color-text-dark, #292522);
}
.ds-heading-title {
  margin: 0;
  font-family: "Bodoni Moda", Georgia, serif;
  font-size: clamp(2.5rem, 4.8vw, 4.4rem);
  font-weight: 400;
  line-height: 0.94;
  letter-spacing: -0.03em;
  text-wrap: balance;
}
.ds-heading-id {
  margin: 0.65rem 0 0;
  color: var(--color-brand-ink, #8C3B00);
  font-size: 0.82rem;
  font-weight: 500;
  line-height: 1.4;
  letter-spacing: 0.015em;
}
